"""Build the offline architecture gallery from native game captures."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]/'build/building-review'
entries=json.loads((root/'manifest.json').read_text())
cards={}
for e in entries:
    split=e['id'].rsplit('-',1)
    pose=split[-1]
    base=split[0] if pose in ['exterior','door','interior','workroom'] else e['id']
    card=cards.setdefault(base,{'id':base,'title':e['title'].split(' · ')[0] if pose in ['exterior','door','interior','workroom'] else e['title'],'region':e['group'],'views':[]})
    card['views'].append({'file':e['file'],'label':e['title'].split(' · ')[-1]})
    assert (root/e['file']).is_file(),e['file']
assert len(entries)==len({e['id'] for e in entries})
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Frostmere · Architecture review</title>
<style>*{box-sizing:border-box}body{margin:0;background:#11191d;color:#e4e6de;font:16px system-ui}header{padding:46px 5vw 28px;background:linear-gradient(120deg,#36423d,#151e26)}small{color:#dbbd83;letter-spacing:3px}h1{font:46px Georgia;margin:15px 0}p{max-width:860px;color:#c0c9c5;line-height:1.65}.stats{color:#e0c592}nav{position:sticky;top:0;background:#11191df5;padding:16px 5vw;z-index:2;display:flex;flex-wrap:wrap;gap:12px;border-bottom:1px solid #3b484c}button,input,select{font:inherit;border:1px solid #69766e;border-radius:5px;background:#24322e;color:#f1eee3;padding:10px;cursor:pointer}input{min-width:270px}main{padding:25px 5vw 60px}#count{color:#b8bda5;margin-bottom:20px}#grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:24px}article{background:#1b282b;border:1px solid #3c4a4a;border-radius:8px;overflow:hidden}article .photo{display:block;padding:0;width:100%;border:0;border-radius:0}article img{display:block;width:100%;aspect-ratio:1.6;object-fit:contain;background:#1d292f}article .body{padding:18px}h2{font:23px Georgia;margin:8px 0 16px}article small{font-size:11px;letter-spacing:2px}article select{width:100%}dialog{background:#111b1e;border:1px solid #8d9989;color:#eee8db;max-width:96vw;width:1340px;border-radius:8px}dialog img{width:100%;display:block}dialog::backdrop{background:#000d}footer{display:flex;gap:15px;align-items:center;justify-content:space-between;margin-top:14px}button:hover{border-color:#e1ba74}button:focus-visible,select:focus-visible{outline:3px solid #e1ba74}a{color:#e1c794}</style>
<header><small>FROSTMERE / REVIEW 03</small><h1>Places with a purpose.</h1><p>Regional buildings with distinct rooflines, masonry, timberwork and furnishings: workshops, homes, libraries, clan halls and coastal stores. This gallery also covers the distant keep, Aeralis pavilions, Crucible foundries and station compartments.</p><p class="stats">25 houses & halls · 8 regional palettes · 116 native game views</p><p>Choose a region, then switch each building between exterior, street approach, interior and workroom views. Click an image to enlarge it. Arrow keys cycle its views; Escape closes it. <a href="../../docs/reference/approved-concept.png">Original approved concept</a></p></header><nav><select id="region" aria-label="Region"><option>All regions</option></select><input id="search" type="search" placeholder="Find a building or landmark" aria-label="Find a building"><button id="reset">Reset</button></nav><main><div id="count" aria-live="polite"></div><div id="grid"></div></main><dialog id="viewer"><img id="large" alt=""><footer><button id="prev" aria-label="Previous view">←</button><span id="caption"></span><button id="next" aria-label="Next view">→</button><button id="close">Close</button></footer></dialog><script>
const data=__DATA__,$=id=>document.getElementById(id);let active=null,pose=0;const selected={};
for(const name of [...new Set(data.map(x=>x.region))]){const o=document.createElement('option');o.textContent=name;$('region').append(o)}
function enlarge(card,i){active=card;pose=(i+card.views.length)%card.views.length;const v=card.views[pose];$('large').src=v.file;$('large').alt=card.title+' · '+v.label;$('caption').textContent=$('large').alt;if(!$('viewer').open)$('viewer').showModal()}
function draw(){const q=$('search').value.toLowerCase(),r=$('region').value,shown=data.filter(x=>(r==='All regions'||x.region===r)&&(x.title+' '+x.id).toLowerCase().includes(q));$('count').textContent=shown.length+' buildings and scene groups';$('grid').replaceChildren();for(const card of shown){const a=document.createElement('article'),b=document.createElement('button'),img=document.createElement('img'),d=document.createElement('div'),label=document.createElement('small'),h=document.createElement('h2'),picker=document.createElement('select');b.className='photo';d.className='body';b.setAttribute('aria-label','Enlarge '+card.title);picker.setAttribute('aria-label',card.title+' view');img.loading='lazy';for(const v of card.views){const o=document.createElement('option');o.textContent=v.label;picker.append(o)}picker.selectedIndex=selected[card.id]||0;function update(){selected[card.id]=picker.selectedIndex;img.src=card.views[picker.selectedIndex].file;img.alt=card.title+' · '+card.views[picker.selectedIndex].label}picker.onchange=update;update();b.onclick=()=>enlarge(card,picker.selectedIndex);label.textContent=card.region;h.textContent=card.title;b.append(img);d.append(label,h,picker);a.append(b,d);$('grid').append(a)}}
$('region').onchange=draw;$('search').oninput=draw;$('reset').onclick=()=>{$('region').selectedIndex=0;$('search').value='';draw()};$('close').onclick=()=>$('viewer').close();$('prev').onclick=()=>enlarge(active,pose-1);$('next').onclick=()=>enlarge(active,pose+1);document.onkeydown=e=>{if(!$('viewer').open)return;if(e.key==='ArrowLeft')enlarge(active,pose-1);if(e.key==='ArrowRight')enlarge(active,pose+1)};draw();</script></html>'''
(root/'index.html').write_text(page.replace('__DATA__',json.dumps(list(cards.values())).replace('</','<\\/')))
print(f'BUILDING_GALLERY_COMPLETE cards={len(cards)} images={len(entries)}')
